cd /workspace && python3 - <<'EOF'
import json, random, subprocess, sys, importlib.util
spec = importlib.util.spec_from_file_location("runmod", "/workspace/run.py")
m = importlib.util.module_from_spec(spec)
try: spec.loader.exec_module(m)
except SystemExit: pass

def gen_case(rng, nops=None):
    ops = []
    prefixes = []
    for _ in range(rng.randint(0, 8)):
        length = rng.choice([0, 1, 5, 16, 17, 18, 23, 32, 48, 64, 65, 70, 96, 127, 128])
        prefixes.append((rng.getrandbits(128), length))
    saves=0
    for _ in range(nops or rng.randint(1, 40)):
        r = rng.random()
        if r < 0.4 and prefixes:
            value, length = rng.choice(prefixes); ops.append(["put", "%032x" % value, length, rng.randint(0, 4194302)])
        elif r < 0.6 and prefixes:
            value, length = rng.choice(prefixes); ops.append(["query", ["%032x" % value]])
        elif r < 0.75:
            ops.append(["query", ["%032x" % rng.getrandbits(128)]])
        elif r < 0.85:
            ops.append(["save"]); saves+=1
        elif r < 0.95 and saves:
            ops.append(["load_saved", rng.randrange(saves)])
        else:
            ops.append(["image_query", ["%032x" % rng.getrandbits(128)]])
    return ops
rng=random.Random(1)
for it in range(20):
    ops=gen_case(rng)
    req={"cases":[{"ops":ops}]}
    try:
        m.parse(json.dumps(req).encode())
    except Exception as e:
        print("case",it,"parse error",e)
        # find the offending op
        for op in ops:
            try:
                m.parse(json.dumps({"cases":[{"ops":[op]}]}).encode())
            except Exception as e2:
                print("  bad op:", op, e2); break
        break
EOF
